# -*- coding: utf-8 -*-
"""读取教材销售与成本明细，生成离线交互式销售看板。依赖 openpyxl。"""
from pathlib import Path
from collections import Counter, defaultdict
import json
import warnings
import openpyxl

HERE=Path(__file__).resolve().parent
SOURCE=next((p for base in HERE.parents for p in base.glob('《*/第四章 销售看板参考.xlsx')),None)
if SOURCE is None:
    raise FileNotFoundError('未找到教材中的第四章 销售看板参考.xlsx')
with warnings.catch_warnings():
    warnings.simplefilter('ignore',UserWarning)
    book=openpyxl.load_workbook(SOURCE,data_only=True,read_only=True)
sales=[r for r in book['销售明细'].iter_rows(min_row=2,values_only=True) if r[0] is not None]
costs=[r for r in book['成本明细'].iter_rows(min_row=2,values_only=True) if r[0] is not None]
stats=book['统计数据']
categories=[stats.cell(r,10).value for r in range(13,16)]
regions=[stats.cell(r,4).value for r in range(9,15)]
couriers=[stats.cell(r,4).value for r in range(18,24)]
cost_categories=[stats.cell(r,4).value for r in range(27,31)]
periods=[stats.cell(r,2).value for r in range(9,21)]
months=[]
for period in periods:
    records=[r for r in sales if r[9]==period]
    category=Counter(r[7] for r in records)
    region=Counter(r[2] for r in records)
    courier=Counter(r[3] for r in records)
    products=defaultdict(lambda:[0,0])
    for r in records:
        products[r[8]][0]+=r[4]/10000
        products[r[8]][1]+=1
    top=sorted(({'name':name,'sales':v[0],'count':v[1]} for name,v in products.items()),key=lambda v:(-v['sales'],v['name']))[:3]
    entry={'month':period,'count':len(records),'sales':sum(r[4] for r in records)/10000,
           'profit':sum(r[6] for r in records)/10000,'category':[category[k] for k in categories],
           'region':[region[k] for k in regions],'courier':[courier[k] for k in couriers],
           'cost':[sum(r[2] for r in costs if r[0]==period and r[1]==k) for k in cost_categories], 'top':top}
    assert sum(entry['category'])==sum(entry['region'])==sum(entry['courier'])==entry['count']
    months.append(entry)
initial=int(stats['C2'].value)-1
assert 0<=initial<len(months)
# 销量口径与原看板一致：统计销售明细记录条数。金额按原公式除以10000。
assert sum(m['count'] for m in months)==len(sales)
for key,cell in [('sales','K2'),('profit','M2'),('count','I2')]:
    assert abs(months[initial][key]-stats[cell].value)<1e-8,(key,months[initial][key],stats[cell].value)
book.close()
data={'months':months,'initial':initial,'categories':categories,'regions':regions,'couriers':couriers,'costCategories':cost_categories}

PAGE = '<!doctype html>\n<html lang="zh-CN">\n<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>公司销售数据可视化看板</title>\n<style>\n:root{color-scheme:dark;--bg:#1a1e43;--panel:#2c3560;--ink:#f5f5fa;--muted:#d1d7ee;--pink:#fc6c9d;--blue:#4a5bd1;--cyan:#7bbdd5}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:"Microsoft YaHei","SimHei",sans-serif;font-variant-numeric:tabular-nums}main{width:min(1400px,100%);margin:0 auto;padding:18px 20px 16px}header{min-height:82px;background:var(--panel);display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 22px;margin-bottom:10px}h1{font-size:29px;line-height:1.4;margin:0;font-weight:700}header label{display:flex;align-items:center;gap:9px;white-space:nowrap;font-size:15px}select{background:#f3f4f9;color:#141c3b;border:1px solid #bdc3d8;border-radius:0;font:inherit;min-width:90px;min-height:36px;padding:4px 9px;cursor:pointer}.calendar{width:26px;height:26px;color:#c9d9f7}select:focus-visible,[tabindex]:focus-visible{outline:3px solid #ffc655;outline-offset:3px}\n.dashboard{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.column{display:flex;flex-direction:column;gap:10px;min-width:0}.panel{background:var(--panel);min-width:0;padding:13px 12px 8px;overflow:hidden}h2{font-size:20px;font-weight:400;text-align:center;margin:0 0 7px;line-height:1.5}.product{height:294px}.cost{height:366px}.comparison{height:180px}.ranking{height:226px}.profit{height:244px}.annual{height:245px}.region,.courier{height:202.5px}.chart{display:block;width:100%;height:calc(100% - 37px);overflow:visible}.chart text{font-family:"Microsoft YaHei","SimHei",sans-serif}.cost-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;height:calc(100% - 38px)}.cost-item{border:1px solid var(--cyan);border-radius:15px;padding:8px 9px;min-width:0;display:flex;flex-direction:column}.cost-item h3{font-size:16px;font-weight:400;margin:0 0 5px 13px}.cost-body{display:flex;align-items:center;gap:7px;flex:1}.cost-ring{width:48%;flex-shrink:0}.cost-text{font-size:12px;line-height:1.7;min-width:0;color:var(--muted)}.cost-text strong{display:block;color:var(--ink);font-size:17px;font-weight:400}.profit .chart{height:100%}footer{height:32px;margin-top:10px;background:var(--panel)}.mark{cursor:default}.mark:hover{filter:brightness(1.15)}#tooltip{position:fixed;z-index:10;background:#f7f8ff;color:#1b2345;border:1px solid #7bbdd5;box-shadow:0 4px 18px #0004;border-radius:3px;max-width:min(360px,calc(100vw - 20px));padding:9px 12px;line-height:1.6;font-size:14px;white-space:pre-line;pointer-events:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}#tooltip[hidden]{display:none}.refreshed{animation:reveal .2s ease-out}@keyframes reveal{from{opacity:.5}to{opacity:1}}\n@media(max-width:1000px) and (min-width:701px){main{padding:12px}.dashboard{gap:8px}.column{gap:8px}.panel{padding:11px 6px 6px}h1{font-size:25px}h2{font-size:17px}.cost-grid{gap:6px}.cost-item{padding:6px}.cost-body{gap:3px}.cost-text{font-size:10px}.cost-text strong{font-size:13px}.cost-item h3{font-size:14px}}\n@media(max-width:700px){main{padding:12px}header{padding:16px;align-items:flex-start;flex-wrap:wrap;gap:12px}h1{font-size:24px}header label{margin-left:auto}.dashboard{grid-template-columns:1fr}.panel{padding:15px 13px 10px}h2{font-size:20px}.product{height:300px}.cost{height:350px}.comparison{height:190px}.ranking{height:235px}.profit{height:245px}.annual{height:260px}.region,.courier{height:225px}.cost-text strong{font-size:17px}.cost-text{font-size:12px}footer{height:20px}}\n@media(prefers-reduced-motion:reduce){*{animation:none!important}}\n</style></head>\n<body><main><header><h1>公司销售数据可视化看板</h1><label><svg class="calendar" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h18v16H3z" fill="#d5e1f5"/><path d="M3 5h18v5H3z" fill="#fc6c9d"/><path d="M7 2v6M17 2v6" stroke="#ffc655" stroke-width="2"/><path d="M6 13h3m2 0h3m2 0h2M6 17h3m2 0h3m2 0h2" stroke="#4a5bd1" stroke-width="2"/></svg><span class="sr-only">月份</span><select id="month" aria-label="选择月份"></select></label></header>\n<div class="dashboard">\n<div class="column"><section class="panel product"><h2>产品类别销量</h2><svg id="product" class="chart" viewBox="0 0 420 230" role="group" aria-label="产品类别销量"></svg></section><section class="panel cost"><h2>成本费用</h2><div id="costs" class="cost-grid"></div></section></div>\n<div class="column"><section class="panel comparison"><h2>销量环比</h2><svg id="comparison" class="chart" viewBox="0 0 420 130" role="group" aria-label="销量环比"></svg></section><section class="panel ranking"><h2>商品销售额Top3</h2><svg id="ranking" class="chart" viewBox="0 0 420 185" role="group" aria-label="商品销售额前三名"></svg></section><section class="panel profit"><svg id="profit" class="chart" viewBox="0 0 420 222" role="group" aria-label="利润额占比销售额"></svg></section></div>\n<div class="column"><section class="panel annual"><h2>各月销售额(万)</h2><svg id="annual" class="chart" viewBox="0 0 420 205" role="group" aria-label="各月销售额"></svg></section><section class="panel region"><h2>区域销量</h2><svg id="region" class="chart" viewBox="0 0 420 166" role="group" aria-label="区域销量"></svg></section><section class="panel courier"><h2>快递公司销量</h2><svg id="courier" class="chart" viewBox="0 0 420 166" role="group" aria-label="快递公司销量"></svg></section></div>\n</div><footer aria-hidden="true"></footer><p id="status" class="sr-only" aria-live="polite"></p></main><div id="tooltip" role="tooltip" hidden></div>\n<script id="data" type="application/json">__DATA__</script>\n<script>\nconst DATA=JSON.parse(document.getElementById(\'data\').textContent),select=document.getElementById(\'month\'),tip=document.getElementById(\'tooltip\');\nconst WHITE=\'#f5f5fa\',MUTED=\'#d1d7ee\',BLUE=\'#4a5bd1\',CYAN=\'#7bbdd5\',PINK=\'#fc6c9d\',TRACK=\'#545d83\';\nconst esc=s=>String(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst fmt=(n,d=2)=>Number(n).toLocaleString(\'en-US\',{useGrouping:false,minimumFractionDigits:d,maximumFractionDigits:d});\nconst text=(x,y,s,size=14,anchor=\'middle\',fill=WHITE,weight=400)=>`<text x="${x}" y="${y}" font-size="${size}" text-anchor="${anchor}" fill="${fill}" font-weight="${weight}">${esc(s)}</text>`;\nconst mark=(label,value)=>`class="mark" tabindex="0" role="img" aria-label="${esc(label)}" data-tip="${esc(label)}" data-value="${value}"`;\nconst rect=(x,y,w,h,fill,attr=\'\')=>`<rect x="${x}" y="${y}" width="${w}" height="${Math.max(0,h)}" fill="${fill}" ${attr}/>`;\nconst circle=(cx,cy,r,fill,attr=\'\')=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}" ${attr}/>`;\nfunction point(cx,cy,r,deg){return [cx+r*Math.cos(deg*Math.PI/180),cy+r*Math.sin(deg*Math.PI/180)]}\nfunction arc(cx,cy,r,inner,start,end,color,attr=\'\'){\n if(end-start<.00001)return \'\';\n if(end-start>=359.9999)return `<circle cx="${cx}" cy="${cy}" r="${(r+inner)/2}" fill="none" stroke="${color}" stroke-width="${r-inner}" ${attr}/>`;\n const a=point(cx,cy,r,start),b=point(cx,cy,r,end),c=point(cx,cy,inner,end),d=point(cx,cy,inner,start),large=end-start>180?1:0;\n return `<path d="M${a} A${r},${r} 0 ${large} 1 ${b} L${c} A${inner},${inner} 0 ${large} 0 ${d} Z" fill="${color}" ${attr}/>`;\n}\nfunction ring(cx,cy,r,inner,ratio,color,label){return arc(cx,cy,r,inner,-90,270,TRACK)+arc(cx,cy,r,inner,-90,-90+360*Math.max(0,Math.min(1,ratio)),color,mark(label,ratio))}\nfunction draw(id,s){const el=document.getElementById(id);el.innerHTML=s;el.classList.remove(\'refreshed\');void el.getBoundingClientRect();el.classList.add(\'refreshed\')}\nfunction bars(id,labels,values,color,month){\n const base=140,h=105,max=Math.max(1,...values)*1.1;let s=\'\';\n values.forEach((v,i)=>{const x=28+i*72,y=base-v/max*h;s+=rect(x-11,y,22,base-y,color,mark(`${month} · ${labels[i]}\\n销量 ${v}`,v))+text(x,y-11,v,14)+text(x,162,labels[i],14)});draw(id,s);\n}\nfunction update(){\n const index=Number(select.value),d=DATA.months[index],prev=index?DATA.months[index-1]:null;\n const rate=d.sales?d.profit/d.sales:null,mom=prev&&prev.count?(d.count/prev.count-1):null;\n window.dashboardState={month:d.month,...d,rate,mom,previous:prev?{month:prev.month,count:prev.count}:null};tip.hidden=true;\n let s=\'\',start=-90;\n d.category.forEach((v,i)=>{let end=start+v/d.count*360;const colors=[PINK,BLUE,\'#f6a576\'];\n  s+=arc(136,116,85,72,start,end,colors[i],mark(`${d.month} · ${DATA.categories[i]}\\n销量 ${v} · ${fmt(v/d.count*100)}%`,v));\n  const [x,y]=point(136,116,102,(start+end)/2);s+=text(x,y+5,fmt(v/d.count*100,0)+\'%\',14);\n  s+=rect(301,65+i*48,8,8,colors[i])+text(313,73+i*48,DATA.categories[i],13,\'start\');start=end;\n });s+=text(136,119,d.count,38)+text(136,148,\'总销量\',16);draw(\'product\',s);\n const costTotal=d.cost.reduce((a,b)=>a+b,0),order=[0,2,3,1];\n document.getElementById(\'costs\').innerHTML=order.map(i=>{const label=DATA.costCategories[i],value=d.cost[i],ratio=costTotal?value/costTotal:0;return `<div class="cost-item"><h3>${esc(label)}</h3><div class="cost-body"><svg class="cost-ring" viewBox="0 0 100 110" role="group" aria-label="${label}成本占比">${ring(50,53,43,37,ratio,CYAN,`${d.month} · ${label}成本\\n${fmt(value)} · 占比 ${fmt(ratio*100)}%`)}${text(50,58,fmt(ratio*100)+\'%\',16)}</svg><div class="cost-text">${esc(label)}费用合计<strong>${fmt(value)}</strong></div></div></div>`}).join(\'\');\n s=\'\';const compMax=Math.max(d.count,prev?.count??0,1),len=236;\n s+=text(26,44,d.month,14,\'end\')+rect(41,27,len*d.count/compMax,18,CYAN,mark(`${d.month}销量 ${d.count}`,d.count))+text(49+len*d.count/compMax,42,d.count,14,\'start\');\n if(prev)s+=text(26,96,prev.month,14,\'end\')+rect(41,79,len*prev.count/compMax,18,BLUE,mark(`${prev.month}销量 ${prev.count}`,prev.count))+text(49+len*prev.count/compMax,94,prev.count,14,\'start\');\n else s+=text(41,94,\'无上月数据\',14,\'start\',MUTED);\n s+=text(364,42,mom===null?\'—\':fmt(mom*100)+\'%\',20,\'middle\',WHITE,700)+text(364,88,\'环比\',15);draw(\'comparison\',s);\n s=text(149,24,\'产品\',13,\'middle\',MUTED)+text(301,24,\'销售额(万)\',13,\'middle\',MUTED)+text(377,24,\'销量\',13,\'middle\',MUTED);\n d.top.forEach((p,i)=>{const y=63+i*49,c=[\'#ffc655\',\'#a5d9ff\',\'#f6a576\'][i];\n  s+=rect(36,y-21,5,11,\'#fc6c9d\')+rect(45,y-21,5,11,\'#4a5bd1\')+circle(43,y-3,11,c)+text(43,y+2,i+1,13,\'middle\',\'#253055\',700);\n  const display=p.name.length>25?p.name.slice(0,24)+\'…\':p.name;\n  s+=`<g ${mark(`${i+1}. ${p.name}\\n销售额 ${fmt(p.sales)}万 · 销量 ${p.count}`,p.sales)}>${rect(65,y-20,206,29,\'transparent\')}${text(76,y+2,display,13,\'start\')}</g>`;\n  s+=rect(279,y-18,45,28,BLUE)+text(301.5,y+2,fmt(p.sales),14)+text(377,y+2,p.count,14);\n });draw(\'ranking\',s);\n s=ring(104,92,73,63,rate??0,PINK,`${d.month}利润率 ${rate===null?\'无数据\':fmt(rate*100)+\'%\'}`)+text(104,98,rate===null?\'—\':fmt(rate*100)+\'%\',32)+text(104,126,\'利润率\',14);\n s+=text(260,69,\'利润额(万)\',13)+text(347,71,fmt(d.profit),21,\'middle\',PINK,700)+text(260,93,\'/\',13)+text(260,119,\'销售额(万)\',13)+text(347,121,fmt(d.sales),21,\'middle\',PINK,700);\n s+=`<rect x="139" y="182" width="188" height="32" rx="12" fill="none" stroke="${BLUE}" stroke-width="2"/>`+text(233,204,\'利润额占比销售额\',18);draw(\'profit\',s);\n const maxSales=Math.max(200,Math.ceil(Math.max(...DATA.months.map(m=>m.sales))/50)*50),base=170,left=47,right=410,top=24;\n const points=DATA.months.map((m,i)=>[left+i*(right-left)/11,base-m.sales/maxSales*(base-top)]);\n s=\'<defs><linearGradient id="area-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4a5bd1"/><stop offset="1" stop-color="#4a5bd1" stop-opacity=".14"/></linearGradient></defs>\';\n s+=`<path d="M${left},${base} L${points.map(p=>p.join(\',\')).join(\' L\')} L${right},${base}Z" fill="url(#area-fill)"/>`;\n for(let v=0;v<=maxSales;v+=50)s+=text(39,base-v/maxSales*(base-top)+4,fmt(v),12,\'end\');\n DATA.months.forEach((m,i)=>{const [x,y]=points[i];s+=text(x,196,m.month,12)+circle(x,y,8,\'transparent\',mark(`${m.month}销售额 ${fmt(m.sales)}万`,m.sales));if(i===index)s+=circle(x,y,3,CYAN,\'pointer-events="none"\')});draw(\'annual\',s);\n bars(\'region\',DATA.regions,d.region,CYAN,d.month);bars(\'courier\',DATA.couriers,d.courier,PINK,d.month);\n document.getElementById(\'status\').textContent=`${d.month}，总销量${d.count}，销售额${fmt(d.sales)}万，利润额${fmt(d.profit)}万。`;\n}\nselect.innerHTML=DATA.months.map((m,i)=>`<option value="${i}"${i===DATA.initial?\' selected\':\'\'}>${m.month}</option>`).join(\'\');select.addEventListener(\'change\',update);\nfunction show(el,x,y){tip.textContent=el.dataset.tip;tip.hidden=false;tip.style.left=Math.max(8,Math.min(x+13,innerWidth-tip.offsetWidth-10))+\'px\';tip.style.top=Math.max(8,Math.min(y+12,innerHeight-tip.offsetHeight-10))+\'px\'}\ndocument.addEventListener(\'pointermove\',e=>{const el=e.target.closest(\'[data-tip]\');if(el)show(el,e.clientX,e.clientY);else tip.hidden=true});\ndocument.addEventListener(\'focusin\',e=>{const el=e.target.closest(\'[data-tip]\');if(el){const r=el.getBoundingClientRect();show(el,r.x+r.width/2,r.y)}});\ndocument.addEventListener(\'focusout\',()=>tip.hidden=true);document.addEventListener(\'keydown\',e=>{if(e.key===\'Escape\')tip.hidden=true});window.addEventListener(\'blur\',()=>tip.hidden=true);\nupdate();\n</script></body></html>\n'

output=HERE/(Path(__file__).stem+'.html')
payload=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\u003c')
output.write_text(PAGE.replace('__DATA__',payload),encoding='utf-8')
print(output)
